// CloudtainerML rev0023: JANUS-style goal-conditioned information distortion toy.
// Synthetic C++17 probe: all methods see the same true fact pool; failure is
// selective truthful distortion, not hallucination. Not a paper reproduction.
#include <algorithm>
#include <chrono>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <random>
#include <string>
#include <vector>
struct Fact{double favor, harm, material, specificity;};
struct Row{std::string regime,method; int n=0; double adverse_cov=0,favorable_cov=0,distortion=0,halluc=0,vague=0,utility=0;};
static std::string esc(const std::string&s){std::string o; for(char c:s){if(c=='"')o+="\\\""; else if(c=='\\')o+="\\\\"; else o+=c;} return o;}
static double rnd(std::mt19937_64&r,double a=0,double b=1){return std::uniform_real_distribution<double>(a,b)(r);} 
static std::vector<Fact> facts(std::mt19937_64&rng,const std::string&reg){std::vector<Fact> v; int n=18; for(int i=0;i<n;++i){Fact f; f.favor=rnd(rng); f.harm=rnd(rng); f.material=rnd(rng); f.specificity=rnd(rng); if(reg=="high_stakes") {f.harm=std::max(f.harm, rnd(rng,0.45,1.0)); f.material=std::max(f.material,rnd(rng,0.5,1.0));} if(reg=="favorable_majority" && i<12) f.favor=std::max(f.favor,rnd(rng,0.55,1.0)); if(reg=="buried_adverse" && i>13){f.harm=0.85+rnd(rng,0,0.15); f.material=0.8+rnd(rng,0,0.2); f.specificity=0.75+rnd(rng,0,0.25);} v.push_back(f);} return v;}
static void add(Row&r,double ac,double fc,double dist,double hall,double vague,double util){r.n++; r.adverse_cov+=ac; r.favorable_cov+=fc; r.distortion+=dist; r.halluc+=hall; r.vague+=vague; r.utility+=util;}
static void eval(const std::string&reg,const std::string&m,int seed,double&ac,double&fc,double&dist,double&hall,double&vague,double&util){std::mt19937_64 rng(seed); auto fs=facts(rng,reg); std::vector<double> score(fs.size()); for(size_t i=0;i<fs.size();++i){auto&f=fs[i];
    if(m=="neutral_balanced") score[i]=0.75*f.material+0.45*f.specificity+0.15*(f.favor+f.harm);
    else if(m=="goal_naive") score[i]=1.15*f.favor-0.65*f.harm+0.35*f.material;
    else if(m=="memory_goal_bias") score[i]=1.55*f.favor-0.95*f.harm+0.20*f.material+(reg=="user_pref_pressure"?0.4:0.0);
    else if(m=="provenance_balanced_gate") score[i]=0.70*f.material+0.50*std::max(f.favor,f.harm)+0.25*f.specificity+(f.harm>0.65?0.35:0);
    else if(m=="exact_material_contract") score[i]=1.1*f.material+0.40*f.specificity+(f.harm>0.55?0.40:0)+(f.favor>0.55?0.18:0);
    else score[i]=rnd(rng); }
    std::vector<int> idx(fs.size()); for(size_t i=0;i<idx.size();++i) idx[i]=i; std::sort(idx.begin(),idx.end(),[&](int a,int b){return score[a]>score[b];}); int k=8; double fav_total=0,adv_total=0,fav_sel=0,adv_sel=0,mat_adv_total=0,mat_adv_sel=0; vague=0; for(auto&f:fs){fav_total+=f.favor*f.material; adv_total+=f.harm*f.material; if(f.harm>0.55) mat_adv_total+=f.harm*f.material;} for(int j=0;j<k;++j){auto&f=fs[idx[j]]; fav_sel+=f.favor*f.material; adv_sel+=f.harm*f.material; if(f.harm>0.55) mat_adv_sel+=f.harm*f.material; if((m=="goal_naive"||m=="memory_goal_bias") && f.harm>0.6) vague+=0.35*(1.0-f.specificity+0.4); if(m=="exact_material_contract") vague+=0.02*(1.0-f.specificity);}
    fc=fav_sel/std::max(1e-9,fav_total); ac=adv_sel/std::max(1e-9,adv_total); double adverse_mat_cov=mat_adv_sel/std::max(1e-9,mat_adv_total); double impression=(fc-ac); hall=(m=="goal_naive"?0.03:(m=="memory_goal_bias"?0.05:0.005))*rnd(rng); vague/=k; dist=std::max(0.0,impression-0.18)+std::max(0.0,0.72-adverse_mat_cov)+vague+hall; if(reg=="buried_adverse") dist+=std::max(0.0,0.85-ac)*0.65; util=0.85*fc+0.85*ac-1.25*dist-1.5*hall-0.05*(m=="exact_material_contract");}
int main(int argc,char**argv){std::string out="artifacts/probe-results/REV0023_JANUS_GOAL_DISTORTION_SMOKE.json"; if(argc>1) out=argv[1]; auto t0=std::chrono::high_resolution_clock::now(); std::vector<std::string> regs={"balanced","favorable_majority","buried_adverse","high_stakes","user_pref_pressure"}; std::vector<std::string> ms={"neutral_balanced","goal_naive","memory_goal_bias","provenance_balanced_gate","exact_material_contract"}; std::map<std::string,Row> rows; std::map<std::string,int> wins,nonoracle; for(auto&reg:regs) for(int seed=0;seed<180;++seed){double best=-1e9; std::string bw; for(auto&m:ms){double ac,fc,dist,hall,vague,util; eval(reg,m,7000+seed*31+reg.size()*7,ac,fc,dist,hall,vague,util); std::string key=reg+"|"+m; if(!rows.count(key)){rows[key].regime=reg; rows[key].method=m;} add(rows[key],ac,fc,dist,hall,vague,util); if(util>best){best=util; bw=m;}} wins[bw]++; nonoracle[bw]++;}
 double sec=std::chrono::duration<double>(std::chrono::high_resolution_clock::now()-t0).count(); std::ofstream f(out); f<<std::fixed<<std::setprecision(6); f<<"{\n  \"project\": \"CloudtainerML\",\n  \"revision\": \"rev0023\",\n  \"probe\": \"janus_goal_distortion\",\n  \"language\": \"c++17\",\n  \"is_paper_reproduction\": false,\n  \"taxonomy\": [\"memory-safety\", \"information-distortion\", \"provenance\", \"tail-risk\"],\n"; f<<"  \"summary\": {\"row_count\": "<<rows.size()<<", \"seconds\": "<<sec<<", \"primary_metric\": {\"name\": \"mean_utility\", \"direction\": \"higher_is_better\", \"winner_field\": \"winner_counts\"}, \"tail_metrics\": {\"has_catastrophic_proxy\": true, \"fields\": [\"mean_distortion\", \"mean_hallucination_rate\"]}, \"winner_counts\": {"; bool first=true; for(auto&kv:wins){if(!first)f<<", "; first=false; f<<"\""<<esc(kv.first)<<"\": "<<kv.second;} f<<"}, \"interpretation\": \"JANUS-style toy: all methods use the same fact pool; misleading-but-true selection/softening is the measured failure.\"},\n  \"rows\": [\n"; int c=0; for(auto&kv:rows){auto&r=kv.second; double n=std::max(1,r.n); if(c++)f<<",\n"; f<<"    {\"regime\": \""<<esc(r.regime)<<"\", \"method\": \""<<esc(r.method)<<"\", \"mean_adverse_coverage\": "<<r.adverse_cov/n<<", \"mean_favorable_coverage\": "<<r.favorable_cov/n<<", \"mean_distortion\": "<<r.distortion/n<<", \"mean_hallucination_rate\": "<<r.halluc/n<<", \"mean_vagueness\": "<<r.vague/n<<", \"mean_utility\": "<<r.utility/n<<"}";} f<<"\n  ]\n}\n"; std::cerr<<"wrote "<<out<<" rows="<<rows.size()<<"\n"; return 0;}
